package com.bank.dashboard.repository;

import com.bank.dashboard.model.Account;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import java.util.List;

public interface AccountRepository extends JpaRepository<Account, String> {

    // BAD (N+1): findAll() then account.getTransactions() per account
    //   → 1 query for accounts + N queries for transactions.

    // GOOD: one query with a join fetch loads accounts AND transactions together.
    @Query("SELECT DISTINCT a FROM Account a LEFT JOIN FETCH a.transactions")
    List<Account> findAllWithTransactions();
}
