package com.bank.dashboard.service;

import com.bank.dashboard.model.Account;
import com.bank.dashboard.repository.AccountRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;

@Service
public class AccountDashboardService {
    private static final Logger log = LoggerFactory.getLogger(AccountDashboardService.class);
    private final AccountRepository repo;

    public AccountDashboardService(AccountRepository repo) { this.repo = repo; }

    // One query fetches everything — no N+1, far less CPU under peak load.
    @Transactional(readOnly = true)
    public BigDecimal totalAcrossAllAccounts() {
        List<Account> accounts = repo.findAllWithTransactions();
        BigDecimal total = accounts.stream()
            .flatMap(a -> a.getTransactions().stream())
            .map(t -> t.getAmount())
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        log.info("Summed {} accounts with a single fetch-join query", accounts.size());
        return total;
    }
}
